import time
import random
import math

def construct(n_rows, k):
    start_time = time.time()
    deadline = start_time + 115  # 5s safety margin for 120s limit

    # Total number of differences to pack: n_rows * k * (k+1) / 2
    # We need to assign distinct difference values to all these slots.
    # The differences are generated by a row of k+1 integers starting at 0.
    # Let the row be 0 = x_0 < x_1 < ... < x_k.
    # The differences are d_{i,j} = x_j - x_i for 0 <= i < j <= k.
    # Note that d_{i,j} = d_{i,i+1} + d_{i+1,i+2} + ... + d_{j-1,j}.
    # Let e_m = x_m - x_{m-1} for m=1..k. These are the "edges" or "steps".
    # Then d_{i,j} is the sum of edges e_{i+1} ... e_j.
    
    # Strategy:
    # 1. Generate a set of N = n_rows * k * (k+1) / 2 distinct small integers (differences).
    # 2. For each row, we need to partition a subset of these differences into k edges such that
    #    all subset sums (contiguous in the edge sequence) are in the assigned set?
    #    No, that's not quite right. The differences are determined by the edges.
    #    If we pick edges e_1..e_k, the set of differences is fixed: {sum(e_{i+1}..e_j) for i<j}.
    #    We need the sets of differences for all rows to be disjoint.
    
    # Alternative Strategy: Constructive
    # We know that Sidon sequences (B_2 sequences) have distinct sums of two elements.
    # Here we have distinct differences, which is similar but for a chain.
    # A row is a "Golomb ruler" if all differences are distinct.
    # We need n_rows Golomb rulers such that no difference value is repeated across rulers.
    
    # This is equivalent to packing n_rows Golomb rulers into the integers such that
    # their difference sets are disjoint.
    
    # Let's try a randomized construction with local search on the edges.
    # State: list of n_rows rows, each represented by its k edges (positive integers).
    # Objective: Minimize max(sum(edges) for all rows), subject to all differences being distinct.
    
    # Initialization: Greedy
    # Start with empty rows.
    # For each row, pick edges one by one to minimize the current max difference conflict.
    # Actually, simpler: Start with random small edges, then repair.
    
    # Let's use a "Conflict Graph" approach.
    # We maintain a global set of used differences.
    # When adding an edge or changing it, we check for conflicts.
    
    # Better: 
    # 1. Generate a pool of candidate difference values (e.g., 1..M).
    # 2. For each row, we want to select k edges such that the resulting difference set
    #    is a subset of the available differences and disjoint from other rows.
    
    # Let's try a direct random search with local improvement.
    # Representation: rows as list of lists of edges.
    # row[i] = [e_1, ..., e_k]. The actual values are cumulative sums.
    
    # Conflict detection:
    # For a given row with edges e, compute all differences.
    # If a difference d is already in used_diffs, it's a conflict.
    
    # To speed up, we can precompute the difference set for a row.
    # But checking distinctness across rows requires a global set.
    
    # Let's stick to the element-wise local search but optimize the inner loop.
    # The previous code was slow because it recalculated deltas or did too many random steps.
    
    # New Approach: 
    # 1. Greedy construction to get a valid (but possibly large) solution.
    # 2. Local search to minimize scope.
    #    Move: Change one element in a row.
    #    Acceptance: Only if it reduces scope and maintains validity (or temporarily allows conflicts to escape?).
    #    Actually, maintaining validity is hard if we start from a valid state and make moves.
    #    If we start valid, any move that keeps it valid and reduces scope is good.
    #    But the search space of valid moves might be small.
    
    # Let's try "Simulated Annealing" on the scope, allowing conflicts temporarily but penalizing them heavily.
    # Objective function: Scope + Lambda * NumConflicts.
    # If we minimize this, we might find a valid solution with small scope.
    
    # Let's refine the previous code's structure but with a more robust conflict handling.
    
    # Data structures:
    # rows: list of lists of values (0, x1, ..., xk)
    # diff_counts: array where diff_counts[d] is count of d.
    # conflicts: number of d with diff_counts[d] > 1.
    
    # We will use the "element move" strategy.
    # To speed up, we precompute the contribution of each element to the conflicts?
    # That's complex.
    
    # Let's try a different initialization: 
    # Use a known Golomb ruler sequence if possible, or random small integers.
    # Then use local search.
    
    # Key optimization: 
    # Instead of random element moves, try "row reconstruction".
    # Pick a row, remove its differences from the global count.
    # Reconstruct the row greedily or randomly to minimize max element, given the available differences.
    # Then add its differences back.
    
    # This is a "row-level" local search.
    
    used_diffs = set()
    rows = []
    
    # Greedy Init
    for _ in range(n_rows):
        row = [0]
        for _ in range(k):
            # Try to find smallest x > row[-1] such that all diffs x-a are new
            x = row[-1] + 1
            while True:
                valid = True
                for a in row:
                    if (x - a) in used_diffs:
                        valid = False
                        break
                if valid:
                    row.append(x)
                    for a in row[:-1]:
                        used_diffs.add(x - a)
                    break
                x += 1
        rows.append(row)
        
    best_rows = [r[:] for r in rows]
    best_scope = max(max(r) for r in rows)
    
    # Local Search State
    current_rows = [r[:] for r in rows]
    
    # We need a fast way to compute conflicts and scope.
    # Let's maintain a global diff_counts array.
    # M_max estimate: best_scope * 2? Or fixed large number.
    # Let's use a dictionary for diff_counts to be safe, or a large array.
    # Array is faster.
    M_max = 10000 # Should be enough for n=4, k=7 (scope ~134)
    
    diff_counts = [0] * (M_max + 1)
    
    def update_row_diffs(row, sign):
        n = len(row)
        for i in range(n):
            for j in range(i+1, n):
                d = row[j] - row[i]
                if d <= M_max:
                    diff_counts[d] += sign
                    
    for r in current_rows:
        update_row_diffs(r, 1)
        
    def get_conflicts():
        # Count d where diff_counts[d] > 1
        c = 0
        for count in diff_counts:
            if count > 1:
                c += 1
        return c
        
    conflicts = get_conflicts()
    
    def get_scope():
        return max(max(r) for r in current_rows)
        
    # Row Reconstruction Move
    # Pick a row index ri.
    # Remove its diffs from global count.
    # Reconstruct the row to minimize max value, given the current available diffs (diff_counts == 1 means available? No, diff_counts[d]==0 means available for new use, but we are reusing the row's own diffs? No, we removed them, so they are 0 now. Other rows' diffs are still there).
    # Wait, if we remove row ri, its diffs become 0 (if they were unique) or decrease.
    # We want to reconstruct row ri such that its new diffs do not conflict with other rows.
    # And we want to minimize the max element of row ri.
    
    def reconstruct_row(ri, time_limit=0.5):
        # Remove current row diffs
        update_row_diffs(current_rows[ri], -1)
        
        # Try to build a new row
        # We want to pick x_1..x_k such that all diffs are not in used_diffs (from other rows).
        # And minimize x_k.
        
        # Greedy with backtracking? Or just greedy smallest.
        # Greedy smallest might get stuck or produce large x_k if small diffs are taken.
        # Let's try a few random restarts of greedy construction.
        
        best_new_row = None
        best_new_max = float('inf')
        
        start_t = time.time()
        
        # Try deterministic greedy first
        row = [0]
        for _ in range(k):
            x = row[-1] + 1
            while True:
                valid = True
                for a in row:
                    d = x - a
                    if d <= M_max and diff_counts[d] > 0:
                        # Conflict with other rows (since we removed current row's diffs)
                        # Note: if d was in current row, diff_counts[d] is now 0 (or decreased).
                        # If d was in another row, diff_counts[d] >= 1.
                        valid = False
                        break
                if valid:
                    row.append(x)
                    break
                x += 1
                if x > best_scope + 50: # Cap to avoid infinite loop
                    break
            if len(row) < k+1:
                break # Failed to complete
        
        if len(row) == k+1:
            new_max = row[-1]
            if new_max < best_new_max:
                best_new_max = new_max
                best_new_row = row[:]
                
        # Try some random perturbations of the greedy choice
        # Or just try a few random valid rows?
        # Random search for a valid row with small max is hard.
        
        # Let's just try the greedy one for now. If it works, it's a valid move.
        # If the greedy row is smaller than the current one, we accept.
        
        if best_new_row is not None:
            # Check if it's actually better (smaller max)
            if best_new_max < current_rows[ri][-1]:
                # Apply
                current_rows[ri] = best_new_row
                update_row_diffs(best_new_row, 1)
                return True
            else:
                # Put back original
                update_row_diffs(current_rows[ri], 1)
                return False
        else:
            # Failed to find a valid row, put back original
            update_row_diffs(current_rows[ri], 1)
            return False
            
    # This simple reconstruction might not be enough.
    # Let's combine with element-wise local search.
    
    # Let's go back to element-wise but optimize it.
    # The bottleneck in the previous code was likely the `calc_delta_dupes` or `apply_move` overhead.
    # We can inline these.
    
    # Let's try a hybrid:
    # 1. Row reconstruction to get a good starting point.
    # 2. Element-wise local search to polish.
    
    # Actually, the previous code's score was 1.78. The inspirations had higher scores.
    # Inspiration 2 (2.10) used "row-reconstruction and local polishing".
    # Let's implement that properly.
    
    # Revised Plan:
    # 1. Greedy Init.
    # 2. Loop:
    #    a. Pick a random row.
    #    b. Try to reconstruct it to minimize its max element, given other rows are fixed.
    #       - Remove diffs.
    #       - Use a local search (element-wise) within that row to minimize max, ensuring no conflicts with other rows.
    #       - If successful and max reduced, accept.
    #    c. If no improvement, try element-wise move on a random element in a random row.
    
    # Let's implement `optimize_row(ri)`:
    #   - Save current row.
    #   - Remove diffs.
    #   - Run local search on this single row to minimize max element, subject to no conflicts with other rows.
    #   - If new max < old max, accept. Else revert.
    
    def optimize_row(ri, max_steps=1000):
        old_row = current_rows[ri][:]
        old_max = old_row[-1]
        
        # Remove diffs
        update_row_diffs(old_row, -1)
        
        # Local search on this row
        # State: row values
        # Objective: minimize row[-1]
        # Constraint: no conflicts with other rows (diff_counts[d] > 0 implies conflict)
        
        row = old_row[:]
        steps = 0
        T = 1.0
        
        while steps < max_steps and time.time() < deadline:
            ei = random.randint(1, k)
            old_val = row[ei]
            lower = row[ei-1] + 1
            upper = row[ei+1] - 1 if ei < k else old_max + 10 # Allow slight expansion
            
            if lower > upper:
                continue
                
            new_val = random.randint(lower, upper)
            if new_val == old_val:
                continue
                
            # Check conflicts for this move
            # We only care about conflicts with OTHER rows.
            # So we check if the new diffs involving ei are in diff_counts (which now excludes current row).
            
            valid = True
            for j in range(len(row)):
                if j == ei:
                    continue
                d_new = abs(row[j] - new_val)
                if d_new <= M_max and diff_counts[d_new] > 0:
                    valid = False
                    break
                d_old = abs(row[j] - old_val)
                # We don't need to check d_old conflicts because we removed them.
                # But we need to ensure we don't create a conflict with ANOTHER element in the SAME row?
                # No, the row must be strictly increasing, so diffs within the row are unique?
                # Wait, the problem says "all differences between two entries of the same row are distinct over all rows".
                # This implies:
                # 1. Within a row, all pairwise differences are distinct?
                #    "distinct over all rows" usually means the set of all differences from all rows is a set (no duplicates).
                #    So yes, within a row, differences must be distinct (Golomb ruler property).
                #    So we must also check that new_val doesn't create a duplicate difference WITHIN the same row.
                
                # Let's check within-row distinctness.
                # If we change row[ei], we must ensure:
                # 1. No conflict with other rows (checked above).
                # 2. No conflict with other elements in the same row (new diffs must be distinct from existing diffs in this row).
                
                # This makes the local search more complex.
                # We need to maintain a set of diffs for the current row.
                
            # This is getting complicated. Let's stick to the global diff_counts.
            # If we remove the row's diffs, diff_counts[d] reflects other rows.
            # When we change an element, we generate new diffs.
            # We must ensure:
            # 1. New diffs are not in diff_counts (other rows).
            # 2. New diffs are not equal to any OTHER diff in the same row (that is not being changed).
            
            # Let's precompute the set of diffs in the current row (excluding those involving ei).
            # This is expensive.
            
            # Alternative: 
            # Just check if the move is valid by temporarily applying it to a local diff set?
            
            # Let's simplify: 
            # We will only accept moves that are "clearly" better and valid.
            # Given the complexity, let's rely on the previous element-wise global search but optimize the speed.
            
            steps += 1
            T *= 0.99
            
        # Revert
        update_row_diffs(row, 1)
        
        # If we found a better row, we should have applied it.
        # But we didn't implement the application logic correctly in the loop above.
        
        # Let's return False for now and use the previous global search.
        return False

    # Given the time, I will stick to the previous global element-wise search but with tighter loop and better initialization.
    # The previous code was 1.78. 
    # Let's try to improve the initialization to be closer to optimal.
    # And use a "steepest descent" style local search: try all possible moves for a random element and pick the best one.
    
    # Let's rewrite the local search to be steepest descent.
    
    def local_search_steepest(max_steps=5000):
        nonlocal best_scope, best_rows, conflicts
        
        steps = 0
        while steps < max_steps and time.time() < deadline:
            ri = random.randint(0, n_rows - 1)
            ei = random.randint(1, k)
            
            row = current_rows[ri]
            old_val = row[ei]
            
            lower = row[ei-1] + 1
            upper = row[ei+1] - 1 if ei < k else best_scope + 5
            
            if lower > upper:
                continue
                
            best_delta = 0
            best_new_val = old_val
            
            # Try all values in [lower, upper]
            # This is O(range) which might be large.
            # Limit range to a small window around old_val?
            # Or sample?
            # Let's sample 10 candidates.
            
            candidates = set()
            candidates.add(old_val)
            for _ in range(10):
                candidates.add(random.randint(lower, upper))
                
            for new_val in candidates:
                if new_val == old_val:
                    continue
                    
                # Calculate delta conflicts
                # Remove old, add new
                delta = 0
                for j in range(len(row)):
                    if j == ei:
                        continue
                    d_old = abs(row[j] - old_val)
                    d_new = abs(row[j] - new_val)
                    
                    if d_old <= M_max:
                        c = diff_counts[d_old]
                        if c == 2:
                            delta -= 1
                    if d_new <= M_max:
                        c = diff_counts[d_new]
                        if c == 1:
                            delta += 1
                            
                # Heuristic: prefer smaller new_val if delta is same
                if delta < best_delta or (delta == best_delta and new_val < best_new_val):
                    best_delta = delta
                    best_new_val = new_val
                    
            if best_new_val != old_val:
                # Apply best move
                apply_move(ri, ei, best_new_val)
                
                if conflicts == 0:
                    cur_scope = get_scope()
                    if cur_scope < best_scope:
                        best_scope = cur_scope
                        best_rows = [r[:] for r in current_rows]
                        
            steps += 1
            
    # Need apply_move and calc_delta_dupes from before.
    
    # Let's just return the best_rows from the greedy init if we don't have time to implement the new search properly.
    # But we have time. Let's implement the steepest descent properly.
    
    # Re-defining helpers for the new strategy
    
    def apply_move(ri, ei, new_val):
        nonlocal conflicts
        row = current_rows[ri]
        old_val = row[ei]
        
        for j in range(len(row)):
            if j == ei:
                continue
            d = abs(row[j] - old_val)
            if d <= M_max:
                old_c = diff_counts[d]
                diff_counts[d] -= 1
                if old_c == 2 and diff_counts[d] == 1:
                    conflicts -= 1
        current_rows[ri][ei] = new_val
        for j in range(len(row)):
            if j == ei:
                continue
            d = abs(row[j] - new_val)
            if d <= M_max:
                old_c = diff_counts[d]
                diff_counts[d] += 1
                if old_c == 1 and diff_counts[d] == 2:
                    conflicts += 1

    # Run steepest descent
    local_search_steepest(max_steps=200000)
    
    return best_rows
